/* carfdeep3.js - field-by-field walkthroughs for C.A.R./SkySlope forms (split 3: leasing, tenancy & property management,
   commercial & business, land/ag/manufactured, new construction). Training reference for Steven Shearrill (LPT Realty) -
   verify every field against the current form revision and LPT broker/TC instructions. Not legal advice. Written 2026-10-26. */
window.CARF_DEEP_EXT=Object.assign(window.CARF_DEEP_EXT||{},{
"ABSPA":[
{s:"Header: parties, lot/tract, public report",d:"Enter buyer names exactly as they will take title and the builder's legal entity as seller. Identify the home by street address plus lot, tract/map number and APN from the builder's lot map. Enter the DRE public report (white report) file number and confirm the buyer received and signed the receipt BEFORE signing (verify on the current form). No report receipt = rescission exposure; confirm with LPT broker/TC."},
{s:"Price, deposits and close of escrow",d:"Enter purchase price, initial deposit (and increased deposit if the builder requires one), and either a fixed COE date or days after acceptance. Builder deposits may be held in the builder's escrow under DRE rules; note whether the deposit is refundable and when. Mismatched deposit amounts between this form and the builder's addendum is a common error - make them agree."},
{s:"Financing and contingency periods",d:"Complete loan type, down payment, interest-rate cap if any, and the loan and appraisal contingency days. Builders often require pre-approval with a preferred lender even if the buyer uses an outside MLO - note that in the financing section. Lender needs this fully executed agreement; builder lender incentives tied to using their lender must be disclosed and compared to outside quotes."},
{s:"Subdivision disclosures, HOA and CFD/Mello-Roos",d:"Check the boxes confirming delivery of the public report, HOA governing documents (CC&Rs, budget, bylaws) and any Mello-Roos/CFD or special-tax notices. Enter HOA dues and any one-time working-capital contribution. Lender will use HOA dues and CFD taxes in DTI, so forward the HOA budget and tax bill to the MLO early."},
{s:"Builder warranty and condition",d:"Describe the builder's warranty (e.g. 1-year fit and finish, 10-year structural per SB 800/Civil Code 895 right-to-repair) and whether a third-party warranty is attached. Note the buyer's right to inspect and the final walk-through/punch-list procedure. Certificate of occupancy must exist for a completed home - lender wants it with the appraisal."},
{s:"Options, upgrades and builder credits",d:"List included upgrades/options and their value, or attach the options addendum, and state any builder credit toward closing costs or rate buydown. Builder credits count toward lender interested-party-contribution caps (typically 3-9% conventional, 6% FHA, 4% VA), so the MLO must see the exact amount before the CD is finalized."},
{s:"Attachments and signatures",d:"Attach the builder's required addenda, the public report receipt, NCA advisory, BIA/agency disclosures and escrow instructions. Buyer and the builder's authorized signer sign with title shown. Register the buyer's agent with the builder at the first visit or the builder may deny buyer-broker compensation - confirm compensation in writing (BRBC or builder registration form)."}],
"AGAD":[
{s:"Reference and property identification",d:"Enter the purchase agreement date, buyer and seller names, property address and every APN included, plus total acreage. Ag deals often cover multiple parcels - a missed APN is a common title problem. Attach a parcel map if the legal description is long."},
{s:"Crops, livestock and equipment included",d:"Itemize growing or harvested crops, livestock and farm equipment that transfer, and whether crop proceeds before COE belong to seller. Note personal property transfers by bill of sale outside the real estate loan - lenders will not finance equipment on a mortgage and may exclude its value from the appraisal."},
{s:"Water rights, wells and irrigation",d:"Identify water sources: wells (with well logs and output tests), surface rights, water district shares or allocations, SGMA groundwater basin status. State which rights transfer and set an inspection period for well yield and water quality. Water is the biggest value driver on ag land; recommend a water-rights attorney or hydrologist - confirm with LPT broker/TC."},
{s:"Ag inspections and contingencies",d:"Set contingency days for soil tests, septic/perc, irrigation systems, pesticide/chemical history, permits (grading, well, ag use) and environmental. These usually need longer than the RPA default 17 days - enter a realistic number. Pair with SALSQ seller answers and the buyer's own experts."},
{s:"Leases, Williamson Act and government programs",d:"Disclose existing farm or grazing leases and whether they survive closing (get estoppels), any Williamson Act/Land Conservation contract (restricts use and lowers taxes; cancellation is costly), and USDA/NRCS or conservation program obligations that transfer with the land. Lender must know about leases and Williamson Act restrictions - they affect value and use."},
{s:"Prorations and allocations",d:"Allocate crop proceeds, growing-crop costs, water assessments, Williamson Act tax benefits and lease rents as of COE. Enter the method (per diem, by harvest) so escrow can compute. Unusual prorations should be reviewed by a CPA."},
{s:"Signatures and attachment",d:"All buyers and sellers sign and date; attach to the purchase agreement and deliver to escrow and lender. Financing note: conventional loans limit acreage and income-producing ag use; most ag purchases use farm-credit, portfolio or USDA products - route to the MLO before the loan contingency is set."}],
"ATCA":[
{s:"Header: lease reference and parties",d:"Enter the lease date, property address and unit, landlord/owner name and every tenant on the lease. If granting permission mid-tenancy, reference the original lease and the date this addendum takes effect."},
{s:"Animal description",d:"For each animal: type, breed, color, approximate weight, age, name, license number and vaccination/rabies proof. Attach a photo if the landlord wants one. Breed matters for the landlord's insurance and HOA rules - verify both before approving."},
{s:"Deposit and pet rent",d:"Enter any additional deposit or monthly pet rent. Since July 1, 2024 (AB 12) the total security deposit, including any pet deposit, is capped at one month's rent for most landlords (two months for qualifying small owners) - do not exceed it. Pet rent is allowed but local rent-control rules may treat it as rent."},
{s:"Rules and tenant responsibilities",d:"Check the rules that apply: leash, waste removal, noise, areas off limits, no breeding, damage repair at tenant cost, flea treatment at move-out. Add HOA animal rules. State what happens on violation (cure notice, removal of animal)."},
{s:"Assistance animals",d:"Service and emotional support animals are reasonable accommodations under fair housing law, not pets: no pet deposit, pet rent or breed limits may be charged. If the tenant presents an assistance animal, do not use the deposit/rent fields - document the accommodation separately and confirm with LPT broker/TC."},
{s:"Signatures",d:"Landlord (or property manager as agent) and all tenants sign and date. Attach to the lease, give the tenant a copy, and update the move-in inspection to note the animal."}],
"BBD":[
{s:"Header",d:"Enter property address and unit, landlord/owner or manager name and all tenant names exactly as on the lease (RLMM). The disclosure is required for all new residential tenancies since Jan 1, 2018 under Civil Code 1954.603."},
{s:"Statutory bed bug information",d:"The pre-printed text describes bed bug appearance, life cycle, signs of infestation and prevention. Do not edit the statutory language. If using an older copy, verify the text matches the current Civil Code 1954.603 wording (verify on the current form)."},
{s:"Reporting procedure and contact",d:"Fill in the name, phone and email the tenant must use to report suspected bed bugs. The landlord must not retaliate for reports and may not show or rent a unit it knows is infested."},
{s:"Delivery and signatures",d:"Deliver with the lease before move-in; tenant signs and dates. Keep in the PM file. If a later inspection finds bed bugs, results must be given to affected tenants within 2 business days and to all tenants if common areas are affected."}],
"BDS":[
{s:"Header: business and parties",d:"Enter the legal business name, DBA, address of premises, seller entity and buyer. Reference the BPA date. Make the business name match the BPA, BOS and escrow instructions exactly."},
{s:"Operations, licenses and permits",d:"Seller lists required licenses (business license, seller's permit, health permit, ABC liquor license), their status and whether they transfer. Liquor licenses go through a separate ABC escrow; health permits often require a new inspection on change of ownership."},
{s:"Premises and lease",d:"Seller discloses the premises lease terms, options, assignment consent requirements, defaults and landlord disputes. Attach the lease. Assignment consent is usually a contingency in the BPA - start it early."},
{s:"Employees",d:"Seller lists employees, pay, benefits, accrued vacation, union or employment agreements and any claims. Accrued vacation must be paid out when employment with the seller ends - address who pays in escrow. Pair with BP-ECET and EEC."},
{s:"Liabilities, litigation, environmental",d:"Seller discloses debts, liens (UCC), tax obligations, pending or threatened litigation, regulatory notices and environmental issues (hazmat, underground tanks). Buyer should run UCC, tax lien and judgment searches through escrow."},
{s:"Financial information",d:"Seller attaches P&Ls, balance sheets, tax returns and sales-tax returns referenced in the disclosure and states whether they are accurate. SBA 7(a) lenders require 3 years of business returns and interim financials - get them in this package. Recommend a CPA review."},
{s:"Signatures and receipt",d:"Seller signs and dates every page as required; deliver to buyer during due diligence. Buyer signs acknowledging receipt. Buyer's due-diligence contingency clock often runs from receipt - calendar it with the TC."}],
"BIRN":[
{s:"Header",d:"Enter landlord or property manager name, the property address and unit applied for, and the applicant's name. Use a separate copy for each adult applicant (three copies are in the file)."},
{s:"Nature and scope of the investigation",d:"Describe the kind of investigative consumer report to be ordered (character, general reputation, mode of living, interviews) and name the investigative consumer reporting agency with its address, phone and website, as Civil Code 1786.16 requires. Ordinary credit/eviction reports are covered by the LRA authorization; this notice is for investigative reports."},
{s:"Applicant's rights",d:"The pre-printed text explains the applicant's right to a copy of the report and to inspect the agency's files. Include the checkbox where the applicant can request a free copy. Do not delete the statutory language."},
{s:"Signature and timing",d:"Applicant signs and dates BEFORE the report is ordered. Keep with the LRA and screening results. Screening must be applied uniformly to all applicants (fair housing); confirm screening criteria with LPT broker/TC."}],
"BLA":[
{s:"Parties and business identification",d:"Enter the seller entity (corporation, LLC, individual) and authorized signers with titles, the business name, DBA, address and type of business. Check whether real property or a lease assignment is included - if real property is included, consider a separate listing agreement for it (verify with LPT broker/TC)."},
{s:"Listing price and term",d:"Enter asking price and whether it includes inventory, FF&E and goodwill. Give a definite start and end date - an exclusive listing without an expiration is unenforceable and a DRE violation. Add any protection period for buyers introduced during the term."},
{s:"Compensation",d:"Enter the commission as a percentage of the sale price or a flat fee, any minimum, and when it is earned and payable (close of escrow, or if seller withdraws). State whether the broker may share with cooperating brokers and how much. Since the 2024 NAR settlement changes, compensation to buyer brokers must be negotiated and documented; do not rely on MLS offers."},
{s:"Assets included/excluded",d:"Specify included assets (FF&E, inventory at cost or counted, goodwill, licenses, trade name, phone numbers, website, customer lists) and excluded assets (cash, receivables, personal vehicles). This list drives the BPA and BP-FFE later."},
{s:"Confidentiality and marketing",d:"Set confidentiality: the broker will require an NDA/CML-CNDA from prospects before releasing financials, and marketing may be blind (no business name). Note whether employees know of the sale."},
{s:"Seller representations and disclosures",d:"Seller confirms authority to sell, no undisclosed liens, financials are accurate and discloses pending issues. Bulk-sale (UCC Division 6), ABC license transfer and tax clearance (CDTFA successor liability) are common issues - recommend attorney and CPA."},
{s:"Signatures",d:"Authorized signers sign with representative capacity; broker or manager countersigns. Give the seller a copy. SBA 7(a) buyers will need 3 years of tax returns and P&Ls - ask the seller to gather these at listing."}],
"BP-APP":[
{s:"Reference",d:"Enter the Business Purchase Agreement date, buyer, seller, business name and total purchase price. Price here must equal the BPA price as amended by any BP-FFE/inventory adjustments."},
{s:"Allocation by asset class",d:"Enter dollar amounts for each IRS Form 8594 class: inventory, FF&E, leasehold improvements, covenant not to compete, goodwill, licenses, real property if any. Confirm the column totals equal the purchase price. Agents should not suggest amounts - allocation drives each party's taxes."},
{s:"Inventory adjustment",d:"State how inventory will be counted at close (physical count, at seller's cost) and whether the price adjusts up or down with the count. Escrow needs this to prepare the final settlement."},
{s:"CPA review and consistency",d:"Both parties must report the same allocation on Form 8594. Add a line confirming each party had the opportunity to consult a CPA before signing. SBA lenders review allocation and FF&E values for collateral - send to the lender."},
{s:"Signatures",d:"Buyer and seller sign and date; deliver to escrow. If allocation changes before close, redo the form rather than hand-editing."}],
"BP-ECET":[
{s:"Reference",d:"Enter the business name, address, and BPA date. Mark the form confidential - it contains employee pay data."},
{s:"Employee information",d:"For each employee: name, position, hire date, pay rate, hours/schedule, exempt or non-exempt status and any written employment agreement. One certificate per employee or a schedule, as the form provides (verify on the current form)."},
{s:"Benefits and accruals",d:"List health benefits, retirement, accrued vacation/PTO balances, bonuses promised, commissions owed. California requires accrued vacation to be paid out at separation from the seller - address in escrow who pays."},
{s:"Employee certification",d:"Each employee signs and dates certifying the information is accurate and that no other promises exist. Employees cannot be forced to sign; plan the timeline and treat refusals as a due-diligence item."},
{s:"Delivery",d:"Deliver to buyer before the due-diligence contingency is removed. Keep copies with EEC estoppels in the escrow file; limit distribution to buyer and advisors."}],
"BP-FFE":[
{s:"Reference",d:"Enter the business name, premises address and the BPA date. State whether this list is attached to the offer or added in escrow."},
{s:"Item schedule",d:"List each item with description, quantity, make/model, serial number, condition and location. Group by area (kitchen, office, warehouse). Serial numbers matter: SBA and equipment lenders use this list as collateral and will file UCC-1s against it."},
{s:"Leased, financed or excluded items",d:"Mark items that are leased (do not transfer unless the lease is assigned), items subject to liens or financing (payoff through escrow) and seller's excluded personal items. Run a UCC search through escrow to confirm no undisclosed liens."},
{s:"Verification",d:"Buyer verifies at a walkthrough before close that every listed item is present and working. Seller warrants the list is complete. Note the date of the walkthrough on the form."},
{s:"Signatures and attachment",d:"Both parties sign; deliver to escrow and attach to the bill of sale (BOS) at close. Values here should match the FF&E line on the BP-APP allocation."}],
"BPA":[
{s:"Parties, business and price",d:"Enter buyer and seller legal entities, business name, DBA and premises address, purchase price, initial deposit and COE. Confirm signers have authority (corporate resolution or LLC operating agreement)."},
{s:"Financing",d:"Complete cash, SBA/bank loan amount and terms, and any seller carryback (note, security agreement and UCC filing). SBA 7(a) is typical - lender needs this BPA, the BP-APP allocation, the lease and 3 years of business tax returns; seller carry on SBA deals is usually on standby. Route to the MLO/SBA lender immediately."},
{s:"Assets and inventory",d:"Describe included assets (FF&E per BP-FFE, goodwill, trade name, licenses, customer lists) and inventory at cost counted at close, with the adjustment method. Exclude cash and receivables unless agreed."},
{s:"Lease assignment or new lease",d:"State whether the premises lease will be assigned (landlord consent needed) or a new lease negotiated, and make landlord consent a contingency with a deadline. Many business sales die on landlord consent - start it the day escrow opens."},
{s:"Contingencies and due diligence",d:"Set day counts for buyer review of financials, BDS, lease, licenses, employee certificates and inspection of premises; financing; license transfer (ABC, health); and franchise approval. Enter realistic periods - SBA closings commonly take 45-90 days."},
{s:"Bulk sale, taxes and clearances",d:"Address bulk-sale notice compliance (UCC 6102 recording/publication, at least 12 business days before close), CDTFA tax clearance, EDD and FTB clearances to avoid successor liability. Escrow handles notices; attorney review recommended."},
{s:"Non-compete, training and transition",d:"Enter covenant-not-to-compete terms (scope, radius, years) and seller training period after close. Allocate value to the covenant consistently with BP-APP."},
{s:"Signatures and escrow",d:"All parties sign with titles; open escrow with a holder experienced in business opportunity escrows. Attach BDS, BP-FFE, BP-APP and NDA. Recommend counsel and CPA for both sides."}],
"BVLIA":[
{s:"Header",d:"Enter buyer names, property address or APN and the VLPA date. Deliver with the offer or as soon as the VLPA is accepted - before the investigation contingency runs."},
{s:"Zoning, use and building feasibility",d:"Review with the buyer that zoning, general plan, setbacks, minimum lot size, coastal/hillside overlays and building permits must be verified with the planning department. A buyer who assumes they can build without checking is the classic land-deal problem."},
{s:"Access, easements and utilities",d:"Cover legal and physical access (recorded easements, private roads, road maintenance agreements), availability and cost of water, sewer or septic (perc test), electricity, gas and internet. Utility extension costs can exceed the land price."},
{s:"Soils, hazards and environment",d:"Note soils/geotechnical reports, fire hazard severity zone, flood zone, seismic, endangered species and wetlands, and prior ag or hazmat use. Insurance availability in high fire zones is now a financing issue - check early."},
{s:"Buyer election and signature",d:"Buyer initials or notes which investigations they will order and signs acknowledging receipt. Keep with the reports. Land loans usually require 25-50% down and lenders may ask for a survey, perc test and utility proof - send the buyer to the MLO before writing the offer."}],
"CCSPA":[
{s:"Public report receipt",d:"Before the buyer signs, confirm they received the DRE public report for the conversion and signed the receipt; enter the file number. Selling before the report issues is a DRE violation - confirm status with the developer's counsel."},
{s:"Unit, price and deposits",d:"Enter unit number, parking/storage assignments, purchase price, initial and increased deposits and estimated COE. Deposits are held under DRE subdivision rules (often impounded until conditions are met) - describe in CEEI."},
{s:"Financing and contingencies",d:"Complete loan and appraisal contingency periods. Conversions frequently fail Fannie/FHA warrantability (presale %, owner-occupancy, reserves, litigation) - the MLO needs the HOA budget, master insurance and project questionnaire early. Allow extra time."},
{s:"Tenant provisions",d:"Complete any existing-tenant right of first refusal, notice periods and relocation terms required by state law and local conversion ordinances. If the buyer is the current tenant, note it. Missing tenant rights can void the sale."},
{s:"HOA and subdivision disclosures",d:"Confirm delivery of CC&Rs, bylaws, budget, reserve study and any Mello-Roos. Enter HOA dues and special assessments. Lender uses dues in DTI."},
{s:"Attachments and signatures",d:"Attach CEEI supplemental escrow instructions and developer addenda (options, upgrades, warranty). Buyer and developer's authorized signer sign; open escrow with the deposit. Confirm buyer-broker compensation with the developer in writing."}],
"COVID":[
{s:"Identify the rent period",d:"Determine whether unpaid rent falls in the COVID protected period (Mar 1 - Aug 31, 2020), transition period (Sep 1, 2020 - Sep 30, 2021) or recovery period (Oct 1, 2021 - Mar 31, 2022), and whether a local ordinance (e.g. LA County) extended protections. Most of these forms are now historical."},
{s:"Pick the matching form",d:"CDC-TD-3 tenant declaration, CRRA repayment agreement, CURC unpaid-rent calculation, NTRA-3 and NTT-CTRA notices, PCQ-CTRA, PMC-CPP-3/PMC-CRP-2/PMC-TP-5 pay-or-quit notices and PRQ-CRP-3/PRQ-TP-6 variants each correspond to one period. Do not use them for post-March 2022 rent - use the standard PRQ."},
{s:"Calculate amounts",d:"Use CURC or the Recovery Period calculation sheet to separate rent by period; COVID-period rent generally cannot be the basis for eviction and is collectible only as consumer debt (small claims)."},
{s:"Serve and document",d:"If any notice is still appropriate, attach required declarations and informational notices, serve lawfully and keep proof of service. Deadlines for most notices have long passed."},
{s:"Get legal advice",d:"Collection of COVID-era rental debt is now a civil/small-claims matter with its own limitations; consult a landlord-tenant attorney before serving or filing anything. Confirm with LPT broker/TC."}],
"CEEI":[
{s:"Escrow identification",d:"Enter escrow holder, escrow number, officer, the CCSPA or subdivision purchase agreement date, unit/project name and the DRE public report file number."},
{s:"Deposit handling",d:"Instruct how deposits are held: impounded in a neutral escrow or trust per DRE conditions, when they may be released to the subdivider (after public report conditions are met, bond posted, or close), and refund conditions. DRE rules may bar release before the report issues - confirm with escrow."},
{s:"Documents escrow must receive",d:"List the public report receipt, HOA governing documents, budget and any CFD/Mello-Roos notices; escrow should not close without buyer's signed receipts."},
{s:"Conditions to close",d:"State conditions: recorded final map/condo plan, release of blanket encumbrances, HOA formation, lender project approval. Lender will need the HOA budget, master policy and project approval before funding."},
{s:"Signatures",d:"Buyer, subdivider and escrow sign; keep with the CCSPA. Changes require a written amendment signed by all parties."}],
"CFK":[
{s:"Parties and property",d:"Enter the owner (or REO seller/buyer) making the payment, every adult occupant by name, and the property address. Check local just-cause and relocation ordinances first - some cities require minimum payments and a specific form."},
{s:"Payment amount and vacate date",d:"Enter the cash amount, the vacate date and time, and whether rent is waived through that date. If the occupants are covered tenants, the payment must at least equal any required relocation assistance."},
{s:"Condition and key return",d:"State required condition (broom clean, personal property removed, no damage beyond existing), keys/remotes/garage openers returned and utilities handled. Attach photos of current condition."},
{s:"Release of payment",d:"Instruct how and when payment is released - typically after inspection and key delivery, via escrow or the property manager. Never pay before possession is confirmed."},
{s:"Signatures and timing",d:"All occupants and the payer sign; give copies. For buyers with owner-occupied financing, occupancy is usually required within 60 days of COE - set the vacate date accordingly and confirm with the MLO. A separate waiver of tenancy rights may need attorney review."}],
"CFPB":[
{s:"Header",d:"Enter tenant names exactly as on the lease and the full property address with unit. Attach to the PRQ, PCQ or NTT being served so both arrive together."},
{s:"Federally backed property determination",d:"Confirm with the owner whether the property has an FHA, VA, USDA, Fannie Mae or Freddie Mac loan or a federal subsidy (Section 8, LIHTC). CARES Act section 4024 still requires a 30-day notice to vacate for nonpayment on covered properties - a 3-day notice can be invalid. Note the determination in the file."},
{s:"Protections and resources text",d:"The pre-printed text points tenants to legal aid, state/local protections and rental assistance. Do not edit; verify the resource list is current on the form."},
{s:"Service and proof",d:"Serve with the underlying notice by personal, substituted, or post-and-mail service; complete a proof of service. Calendar the correct notice period (30 days for covered properties) before any unlawful detainer. Recommend landlord-tenant counsel."}],
"CL":[
{s:"Parties and premises",d:"Enter landlord and tenant exact legal entity names and entity type/state, and describe the premises: address, suite, rentable and usable square feet, parking spaces, storage and common areas. Check signers' authority - a lease signed by the wrong entity is a recurring problem."},
{s:"Term and commencement",d:"Enter term length, commencement and expiration dates, any early-occupancy or rent-abatement period, delivery conditions and a holdover rate. If commencement depends on landlord work, define it by event with an outside date."},
{s:"Rent, increases and deposit",d:"Enter base rent per month (and per sq ft), scheduled increases or CPI adjustments, late charges, and security deposit (commercial deposits are not capped like residential). Enter where and how rent is paid."},
{s:"Expense structure",d:"Check gross, modified gross or NNN and complete tenant's pro-rata share of CAM, taxes and insurance, base-year or expense-stop if any, estimates and annual reconciliation procedure. Add caps on controllable CAM if negotiated."},
{s:"Use, improvements and options",d:"Describe the permitted use and exclusives, landlord work/TI allowance, who holds permits, signage, and options to renew/expand with notice windows. Define ADA/CASp responsibility (attach CLCA)."},
{s:"Maintenance, insurance and assignment",d:"Allocate maintenance (HVAC, roof, structure vs interior), required tenant insurance limits and landlord as additional insured, indemnity, and assignment/subletting consent standards. Environmental: if hazmat will be used, attach CML-LEC."},
{s:"Guaranty and attachments",d:"Attach the guaranty signed by the guarantor personally (not the entity), CLCA, rules and regulations, exhibits (floor plan, work letter) and any environmental addendum. Attorney review is recommended for both sides - the form defaults rarely fit."},
{s:"Signatures and delivery of possession",d:"Authorized signers sign with titles and date. Deliver keys only after the signed lease, deposit, first month's rent and certificate of insurance are received. Upload the executed lease to SkySlope with the LCA or LL compensation agreement."}],
"CLCA":[
{s:"Header",d:"Enter landlord, tenant and premises address exactly as on the commercial lease (CL) and the lease date. Required by Civil Code 1938 for every commercial lease, renewal or amendment that extends the term."},
{s:"CASp inspection status",d:"Check whether the premises HAS or HAS NOT been inspected by a Certified Access Specialist. If inspected, check whether it met applicable standards and attach the disability access inspection certificate or report (report delivery can be subject to the tenant's confidentiality agreement)."},
{s:"Statutory notice if not inspected",d:"If not inspected, the form includes the mandatory Civil Code 1938(e) statement that the tenant may request a CASp inspection and that the parties will agree in writing who pays for the inspection and any corrections. Complete the allocation of cost if the lease does not already."},
{s:"Signatures",d:"Both parties sign and date at lease signing; attach to the lease before possession. Never state a space is ADA compliant without a CASp report - exposure under ADA/Unruh."}],
"CLR":[
{s:"Reference and parties",d:"Enter the original lease date, property address and unit, and every landlord and tenant on the lease. All co-tenants must sign or the non-signing tenant may remain liable - or remain in possession."},
{s:"Termination date and condition",d:"Enter the agreed termination date and time, required condition (clean, personal property removed), key and remote return, and final utility reading."},
{s:"Rent and early-termination payment",d:"State rent owed through the termination date, any early-termination fee paid by the tenant or payment to the tenant (cash for keys), and when it is paid. Prorate if the date is mid-month."},
{s:"Security deposit",d:"Describe the pre-move-out inspection right and that the deposit, less lawful deductions with itemization and photos, will be returned within 21 days of vacating under Civil Code 1950.5. Enter the tenant's forwarding address."},
{s:"Release and signatures",d:"Include mutual release language as the form provides, then all landlords and tenants sign and date. For rent-controlled or just-cause units, voluntary termination agreements may require specific disclosures (buyout notice rules in SF, LA, etc.) - check the local ordinance and confirm with LPT broker/TC."}],
"CML-CNDA":[
{s:"Parties and property",d:"Enter the disclosing party (owner/seller or listing broker) and the receiving party (prospective buyer/tenant entity and principals), and identify the property or business. Add the broker as a party if the broker is the one releasing materials."},
{s:"Confidential information defined",d:"Define covered materials: rent rolls, leases, operating statements, tax returns, tenant information, offering memorandum. Exclude public information. Note that tenant personal data should be redacted where possible."},
{s:"Permitted use and recipients",d:"State the information may be used only to evaluate the transaction and shared only with named advisors (attorney, CPA, lender, partners). Make sure the recipient's LENDER is a permitted recipient - commercial lenders will need the rent roll and leases for underwriting."},
{s:"Return, destruction and term",d:"Specify return or destruction of materials if no deal, the confidentiality duration (often 1-2 years) and remedies. Add a non-circumvention clause if the owner requires one."},
{s:"Signature and log",d:"Prospect signs before receiving anything; keep a recipient log (who, what, date) - sellers often require it. Upload to the listing file."}],
"CML-EIA":[
{s:"Reference",d:"Enter the underlying CPA or commercial lease date, parties, property address and APN. Use when a historic use (gas station, dry cleaner, auto, manufacturing) or the lender requires environmental review."},
{s:"Reports to be ordered",d:"Check which assessments will be ordered: Phase I ESA (ASTM E1527-21), Phase II sampling if recommended, asbestos, lead, mold, radon, underground storage tank search; specify who orders and who pays. Phase I turnaround is typically 2-4 weeks."},
{s:"Environmental contingency period",d:"Enter the number of days after acceptance for the environmental contingency and the cancellation right if results are unacceptable. Do not let it expire before the Phase I is delivered - extend in writing with an amendment."},
{s:"Remediation and responsibility",d:"Allocate responsibility for pre-existing contamination versus conditions caused during the tenant's occupancy, cost caps, and whether the seller must remediate before close or credit the buyer. CERCLA liability can attach to a new owner - counsel and environmental consultant recommended."},
{s:"Disclosures and signatures",d:"Attach any known reports and hazmat disclosures. All parties sign; deliver to escrow. Commercial and SBA lenders nearly always require a Phase I (or transaction screen) before funding - build it into the loan timeline."}],
"CML-LEC":[
{s:"Reference",d:"Enter landlord, tenant, premises and the commercial lease date this consent supplements. Use when the lease prohibits hazardous materials but the tenant's operation needs them."},
{s:"Hazardous materials schedule",d:"List each material, maximum quantity on site, storage method/location, use and the applicable permit (fire department, CUPA, air district). Attach SDS sheets if the landlord requires."},
{s:"Compliance duties",d:"Tenant agrees to comply with environmental laws, keep permits current, and provide copies of inspections, notices of violation and spill reports. Add landlord inspection rights."},
{s:"Insurance, indemnity and exit",d:"Set pollution liability insurance limits, indemnity for releases, and end-of-term obligations: removal of materials, decommissioning, and possibly an exit environmental report at tenant cost. Check the landlord's lender and insurer for restrictions on hazmat use."},
{s:"Signatures",d:"Authorized signers for both parties sign; attach to the lease. Keep the schedule updated by written amendment when materials change."}],
"CML-REL":[
{s:"Parties and transaction",d:"Identify all parties, brokers, the agreement being released (CPA, CL or other), its date, escrow number and property address."},
{s:"Claims released and excluded",d:"Describe the released claims (all claims arising from the agreement) and any excluded obligations (confidentiality, indemnities that survive). The form includes a Civil Code 1542 waiver of unknown claims - each party should consult counsel."},
{s:"Deposit and fees",d:"State how the escrow deposit is disbursed (to buyer, seller or split), who pays escrow cancellation and title fees, and any consideration paid for the release."},
{s:"Broker compensation",d:"Address whether brokers waive or retain any claim to compensation on cancellation; confirm with LPT broker/TC before signing on behalf of the brokerage."},
{s:"Signatures and delivery",d:"All parties sign; deliver to escrow - escrow will not release funds without matching signed instructions from both sides. Keep in the SkySlope file as the cancellation document."}],
"CNC-PA":[
{s:"Reference",d:"Enter RPA date, buyer, seller/builder and property address. Use when the builder accepts the RPA for a completed new home instead of its own contract."},
{s:"Builder warranties",d:"Describe the builder's warranties (fit-and-finish, systems, structural per Civil Code 895 et seq.) and whether a third-party warranty is attached; state that warranties transfer to buyer at close. Get the warranty booklet into the file."},
{s:"Permits and certificate of occupancy",d:"Require final permit sign-offs and a certificate of occupancy (or final inspection card) before COE and attach copies. Lender needs the CO and may order a 1004D completion certificate; FHA/VA new construction needs builder certifications and warranty forms."},
{s:"Final walk-through and punch list",d:"Set the walk-through date, how punch-list items are documented, completion deadline and any holdback in escrow for incomplete items. Recommend an independent home inspection even on new construction."},
{s:"Signatures",d:"All parties sign; attach to the RPA with the NCA advisory. Confirm buyer-agent registration and compensation with the builder."}],
"CTT":[
{s:"Header",d:"Enter all tenant names, the property address and unit, and the date of the current rental agreement. Use CTT-2 for a second notice in the same file."},
{s:"Change in terms",d:"State the specific change (new rent amount, new rule, fee, utility responsibility) and the effective date. Rent increases: 30 days' notice if 10% or less in 12 months, 90 days if more (Civil Code 827); add 5 days if mailed."},
{s:"Rent cap check",d:"For AB 1482-covered units, increases are capped at 5% + CPI, max 10%, in any 12 months, with no more than 2 increases per year; local rent control may be lower. An increase over the cap is void - verify coverage before serving."},
{s:"Service and proof",d:"Landlord or agent signs; serve personally, by substituted service, or by mail (adding days). Keep proof of service with the lease. Changes other than rent on a month-to-month tenancy take 30 days."}],
"DRA":[
{s:"Header",d:"Enter applicant names, property address and the application date. Use for denials AND for approvals with less favorable terms (higher deposit, cosigner) based on a consumer report."},
{s:"Decision and reason",d:"Check the reason category consistent with the landlord's written screening criteria (income, credit, rental history). Source of income including Section 8, criminal history outside allowed limits, and protected characteristics cannot be grounds."},
{s:"Consumer reporting agency",d:"Enter the screening company's name, address and toll-free phone, and the statement that the agency did not make the decision and cannot explain it, as FCRA adverse-action rules require."},
{s:"Applicant rights",d:"Include the right to a free copy of the report within 60 days and to dispute inaccuracies, and, where a credit score was used, the score disclosure (verify on the current form)."},
{s:"Delivery and refund",d:"Send promptly by mail or email and keep with the application file. Refund any unused portion of the screening fee as Civil Code 1950.6 requires and provide the receipt/itemization."}],
"EEC":[
{s:"Reference",d:"Enter the business name, address and BPA date. One certificate per employee; use alongside BP-ECET during due diligence."},
{s:"Employment facts",d:"Fill in employee name, job title, hire date, pay rate, schedule, benefits and any written agreements (employment, commission, non-compete). Pre-fill from seller records so the employee confirms or corrects."},
{s:"Claims and side agreements",d:"The employee states whether they have claims for unpaid wages, overtime, harassment, or promises of bonuses/raises not disclosed. This is what protects the buyer; blanks should be filled with 'none' rather than left empty."},
{s:"Signature and delivery",d:"Employee signs and dates; deliver to buyer and escrow before the due-diligence deadline. Employees may decline; keep confidential."}],
"EL":[
{s:"Reference",d:"Enter the original lease date, property address and unit, and all landlord and tenant names. Sign before the original expiration or the tenancy converts to month-to-month."},
{s:"New term",d:"Enter the new expiration date (or new term length) and whether the lease then continues month-to-month."},
{s:"Rent and deposit",d:"Enter the new rent and effective date if changed. The increase must comply with AB 1482 (5% + CPI, max 10%) or local rent control, and Civil Code 827 notice periods still apply. Any deposit increase must stay within the one-month cap (AB 12)."},
{s:"Other terms",d:"State that all other lease terms remain, or list changes (pets, occupants, parking). Re-deliver any disclosures that have changed (RCJC status, TRPR offer annually)."},
{s:"Signatures",d:"All landlords and tenants sign. Lenders use a signed extension to count rental income on investment-property purchases and refinances - give the owner a copy."}],
"FEHN":[
{s:"Header",d:"Enter tenant names, property address and unit exactly as on the lease, and the termination date of the tenancy."},
{s:"Inspection date and time",d:"Enter the agreed date and a time window during normal business hours (unless the tenant agrees otherwise). The inspection must be no earlier than two weeks before move-out."},
{s:"Who will inspect",d:"Identify the landlord, property manager or agent performing the inspection. The tenant may be present."},
{s:"Service",d:"Deliver personally, leave with a suitable person, or mail early enough that the tenant has a full 48 hours (mailing adds time). The tenant can waive the 48-hour notice in writing. Keep proof of service."},
{s:"Follow-up",d:"At the inspection complete the PMOI statement listing items the tenant can fix. Take photos - AB 2801 requires photo documentation for deposit deductions."}],
"FLTN":[
{s:"Header",d:"Enter tenant names, landlord name and property address. Civil Code 1632 applies when the lease was negotiated primarily in Spanish, Chinese, Tagalog, Vietnamese or Korean."},
{s:"Language of negotiation",d:"Check the language used. If an agent negotiated in that language on the landlord's behalf, the requirement applies."},
{s:"Translation provided",d:"Note whether a translated copy of the lease was delivered before signing. C.A.R. publishes translated reference versions of the RLMM - the English version remains the binding document."},
{s:"Signatures and file",d:"Tenant signs acknowledging receipt. Keep with the lease. Failure to provide a required translation lets the tenant rescind the lease."}],
"HPID":[
{s:"Header",d:"Enter landlord (housing provider) and tenant names, property address and lease date. Required by Civil Code 2924.85 when a notice of default has been recorded before the lease is signed."},
{s:"Statutory disclosure",d:"The form contains the required statement that the property is in foreclosure because the owner defaulted on the mortgage, in the mandated language. Do not alter. Enter the recording date if the form provides a field (verify on the current form)."},
{s:"Tenant rights",d:"Explain that a bona fide tenant may stay through a fixed term (unless a buyer will occupy) or receive at least 90 days' notice under state law and the Protecting Tenants at Foreclosure Act."},
{s:"Signatures and delivery",d:"Landlord and all tenants sign before the lease is signed; attach to the lease and give the tenant a copy. Use HPID rather than the older LID unless LPT broker instructs otherwise. Failure to disclose allows the tenant to void the lease and recover rent."}],
"LCA":[
{s:"Choose the version",d:"Use the 'Seller' (landlord pays) version when the owner or landlord agrees to pay the broker, or the 'Buyer' (tenant pays) version when the tenant agrees to pay their broker. Do not use if an LL or PMA already covers the fee."},
{s:"Parties and property",d:"Enter the paying party's legal name, the brokerage name and DRE license number, the agent, and the property address/unit being leased."},
{s:"Compensation",d:"Enter a flat fee or a percentage of the first month's rent or of total lease consideration, and how renewals, extensions or a later purchase by the tenant are treated. Under post-NAR-settlement rules, compensation must be in a signed written agreement before services are rendered - confirm with LPT broker/TC."},
{s:"When earned and payable",d:"State that compensation is earned upon lease execution (or possession) and when it is payable (at signing, from first rent). Add holdover/extension language if the base agreement lacks it."},
{s:"Signatures",d:"Paying party and broker sign and date before the lease is signed. Deliver a copy to the client and upload to SkySlope with the lease. An oral promise to pay a lease commission is hard to enforce."}],
"LID":[
{s:"Header",d:"Enter landlord name, tenant names, premises address and the lease date. Older form - the HPID ('housing provider') version is preferred for new leases."},
{s:"Notice of default details",d:"State that a notice of default has been recorded; enter the recording date and county from the recorded notice."},
{s:"Statutory language",d:"Review the printed Civil Code 2924.85 language with the tenant: foreclosure could end or change the tenancy, and tenant rights under PTFA/state law."},
{s:"Signatures and delivery",d:"Every adult tenant signs, then the landlord/manager. Attach to the lease and give a full copy before collecting rent or a deposit. Non-disclosure lets the tenant void the lease and recover rent and deposits."}],
"LL":[
{s:"Owner, property and term",d:"Enter owner names (as on title), property address and unit, and a specific listing start and expiration date - an exclusive without an expiration is unenforceable. Confirm the owner can lease (HOA rules, lender consent on some loans, local STR/rent-control status)."},
{s:"Lease terms owner will accept",d:"Complete asking rent, security deposit (max one month under AB 12 for most owners), lease length, move-in date, pets, smoking, utilities, parking and occupancy limits. Record AB 1482 coverage or exemption so the RCJC is prepared correctly."},
{s:"Broker compensation",d:"Enter the leasing fee as a flat amount or percentage of rent/lease value, when earned (upon lease execution) and any renewal/extension fee. State what, if anything, is offered to cooperating brokers - MLS offers of compensation are no longer permitted in many MLSs after the NAR settlement; put it here instead."},
{s:"Marketing authority",d:"Check MLS entry (and the seller's/owner's instruction on MLS timing per CRMLS rules), lockbox/keysafe, signage, photos and internet advertising. Note if the property is currently tenant-occupied - showings need NOE notices."},
{s:"Disclosures and screening",d:"Review fair housing, source-of-income rules, screening criteria, RPOD/RPOI owner disclosures, flood (TFHD), bed bug (BBD) and lead paint requirements. Attach the agency disclosure (AD) if required by LPT policy."},
{s:"Signatures",d:"Owner(s) and broker/agent sign and date; give the owner a copy, enter in the MLS within the required time and upload to SkySlope. Confirm with LPT broker/TC whether the office handles rentals and property management."}],
"LRA":[
{s:"One copy per adult",d:"Give each adult applicant their own copy (four identical copies are in the file). Enter the property address, unit, rent amount and date received at the top."},
{s:"Applicant identity and history",d:"Applicant completes full name, DOB, SSN/ITIN (or alternative ID - landlords may not refuse an application solely for lack of SSN), current and prior addresses with landlord contacts, reasons for leaving, vehicles, pets and other occupants."},
{s:"Employment and income",d:"Employer, position, length, gross income and other income sources; attach pay stubs or bank statements. Apply the same income standard to every applicant; for voucher holders, apply the standard to the tenant's share only."},
{s:"Screening fee",d:"Enter the fee charged, which may not exceed actual out-of-pocket cost or the CPI-adjusted cap under Civil Code 1950.6 (about $67 in 2025 - verify the current figure), itemize costs and give a receipt. Since 2025 (AB 2493) no fee may be charged when no unit is available, and unused fees must be refunded."},
{s:"Authorization and signature",d:"Applicant signs authorizing credit, eviction and background reports and verification of references. If an investigative report will be ordered, also use BIRN. Keep the application with the screening report."},
{s:"After screening",d:"If denied or approved on worse terms, send the DRA adverse-action notice and refund unused fees. Apply current limits on criminal history and source-of-income screening. Keep records for fair housing defense."}],
"LRM":[
{s:"Header",d:"Enter property address, unit and the lease date; LRM-1 and LRM-2 are identical copies for separate units or tenancies in the same file."},
{s:"Known mold disclosure",d:"Disclose known mold, past water intrusion, leaks or prior remediation in the space provided and attach reports. Health & Safety Code requires disclosure of known mold exceeding permissible limits; this does not replace repair duties."},
{s:"Tenant ventilation duties",d:"Review the tenant's obligations: run bathroom/kitchen fans, keep surfaces dry, avoid blocking vents, report leaks and visible mold in writing promptly."},
{s:"Signatures",d:"All adult tenants and landlord sign and date; attach to the lease, keep copies in the PM file and calendar moisture checks if issues were disclosed."}],
"MH-PA":[
{s:"Home identification",d:"Enter the HCD decal (license) number, serial/VIN numbers for each section, make, model, year and dimensions. Check whether the home is REAL property (HCD Form 433A recorded, permanent foundation) or PERSONAL property (HCD title and registration transfer)."},
{s:"Park approval contingency",d:"If in a park, enter the deadline to submit the park application and the approval period; buyer must be approved by park management before close. Missing park approval is the most common deal-killer. Attach the park's rental agreement and rules delivery requirement."},
{s:"Space rent and park terms",d:"Enter current space rent, lease term, utilities included, and any rent-control status under the Mobilehome Residency Law and local ordinances. The lender counts space rent in DTI."},
{s:"Title, taxes and fees",d:"Allocate HCD title transfer fees, tax clearance certificate from the county, foundation (433A) certification, and inspections (HUD/engineer certification for permanent foundation). Personal-property homes may be subject to sales tax or in-lieu license fees - escrow should confirm."},
{s:"Financing note",d:"FHA, VA and conventional loans require real property on a permanent foundation with an engineer's certification and HUD tags; otherwise chattel financing (higher rate, shorter term). Route to the MLO before writing - also confirm the home's age (pre-1976 homes are generally not financeable)."},
{s:"Signatures and attachments",d:"Both parties sign; deliver to escrow with the MHTDS (manufactured home TDS). Broker licensing rules apply to personal-property mobile home sales - confirm with LPT broker/TC."}],
"MHDA":[
{s:"Dealer identification",d:"Enter the dealer's legal name, HCD dealer license number, address, phone and salesperson. Required when a licensed manufactured home dealer sells a new or used home as part of the transaction."},
{s:"Home and warranties",d:"List model, serial numbers, HUD label numbers and the manufacturer's and dealer's warranties (new homes carry a statutory 1-year warranty under Health & Safety Code 18046 - verify on the current form)."},
{s:"Delivery, installation and title",d:"Describe who handles transport, setup, foundation, utility hookups, HCD installation permit/certificate and who files HCD title paperwork and when. Lender needs the dealer invoice, installation certificate and 433A/engineer foundation certification for a real-property loan."},
{s:"Compensation",d:"Keep dealer compensation and real estate broker compensation separate and disclosed; the broker should not be paid through the dealer invoice."},
{s:"Signatures",d:"Buyer, seller and dealer sign and date; attach to the purchase agreement and give a copy to escrow."}],
"MHLA":[
{s:"Home identification",d:"Enter HCD decal and serial numbers, make/model/year and whether the home is real or personal property. Attach the HCD registration card or title."},
{s:"Park information",d:"Provide park name, space number, current space rent, lease type and the park approval process; seller must supply park rules and the rental agreement to buyers."},
{s:"Broker eligibility",d:"Confirm the broker may list: real estate brokers may sell manufactured homes that are real property, or personal-property homes registered with HCD (at least one year old since first sale) - a new home requires a dealer license. Verify before marketing."},
{s:"Seller duties and disclosures",d:"Note seller will provide MHTDS, tax clearance and HCD title documents and disclose park notices or rent increases."},
{s:"Signatures",d:"Seller and listing broker sign at listing; attach to the listing agreement and upload both to the SkySlope listing file."}],
"MII":[
{s:"Choose the version",d:"Use the Agent Version when the property manager walks the unit; the Tenant Version lets the tenant document condition within a few days of move-in. Enter property, unit, tenant names and move-in date."},
{s:"Room-by-room condition",d:"For each room note walls, ceilings, floors, windows/screens, doors/locks, fixtures, appliances, smoke/CO detectors and existing damage. Write specifics (e.g. 'nail holes north wall'), not just 'OK'."},
{s:"Photos and video",d:"Take dated photos/video of every room and reference the file names. For tenancies beginning on or after July 1, 2025, AB 2801 requires move-in photos to support any later deduction - keep them with the file."},
{s:"Keys and utilities",d:"Record keys, remotes, mailbox keys and garage openers issued, and utility meter readings on move-in."},
{s:"Signatures",d:"Landlord/agent and tenant sign and date; give the tenant a copy and keep the original with the SUM-MII for move-out comparison."}],
"MOI":[
{s:"Setup",d:"Pull the signed MII and SUM-MII. Enter property, unit, tenant names and move-out date; note whether a pre-move-out inspection (PMOI) was done."},
{s:"Condition comparison",d:"Walk each room and record condition versus move-in; describe damage beyond ordinary wear and tear specifically and distinguish cleaning from repair."},
{s:"Photos",d:"Take dated photos after move-out and again after repairs/cleaning - AB 2801 (effective April 1, 2025) requires both sets to accompany the itemized deduction statement. Reference them on the form."},
{s:"Keys and forwarding address",d:"Record keys/remotes returned and the tenant's forwarding address for the deposit statement."},
{s:"Deposit accounting",d:"Sign and date; give the tenant a copy. Use with the itemized statement, receipts/estimates and photos sent within 21 days of vacating under Civil Code 1950.5. No charges for normal wear and tear."}],
"NCA":[
{s:"Header",d:"Enter buyer names and the project/property or lot. Deliver at or before the builder visit when possible; the first-visit registration issue is addressed here."},
{s:"Builder contract and deposit risk",d:"Review that the builder's contract (not the RPA) usually governs, deposits and upgrade deposits can be nonrefundable, and contingencies are limited. Recommend attorney review of builder contracts."},
{s:"Delays, warranties and inspections",d:"Cover completion delays, builder warranty scope (Civil Code 895 right-to-repair process), HOA and Mello-Roos/CFD taxes, and the recommendation for independent inspections at pre-drywall and final."},
{s:"Agent role and compensation",d:"Explain that the buyer's agent must be registered with the builder (often at first visit) or the builder may refuse compensation, and that the agent does not supervise construction. Document compensation in writing (BRBC)."},
{s:"Lender incentives",d:"Builder-preferred lender incentives must be compared with outside quotes; rate locks for long builds need extended-lock programs. Loop in the MLO before the buyer commits."},
{s:"Signature",d:"Buyer signs and dates the acknowledgment; keep in the file."}],
"NCA-OU":[
{s:"Reference",d:"Enter the new construction agreement date, buyer, builder and lot/address. Use when the buyer selects options or upgrades with the builder during or after signing."},
{s:"Option schedule",d:"List each option with description, location in the home, price and selection date. Running total should reconcile to the final price."},
{s:"Deposits",d:"Enter upgrade deposits, whether refundable, and whether they are credited to the price at close. Nonrefundable upgrade deposits are common - the buyer should understand the risk."},
{s:"Deadlines and change orders",d:"Note selection cutoffs, the change-order process and late-change fees."},
{s:"Signatures and distribution",d:"Buyer and builder's representative sign; send to lender, appraiser contact and escrow so the contract price matches. Option pricing changes LTV and appraisal; seller-paid upgrades may count as concessions."}],
"NCEI":[
{s:"Escrow identification",d:"Enter escrow holder, number, the subdivision purchase agreement date, lot/unit and project name, and the DRE public report number."},
{s:"Public report receipt",d:"Instruct escrow to obtain the buyer's signed receipt for the public report and any amendments before close."},
{s:"HOA items",d:"Address delivery of HOA governing documents, budget, assessment amounts and any initial contributions. Lender may require project approval and the HOA budget - get these early."},
{s:"Deposit handling",d:"Describe how deposits are held and released under DRE subdivision rules (impound or bond) and refund conditions."},
{s:"Signatures and tracking",d:"All parties sign; deliver to escrow and track receipts in the file."}],
"NCNC":[
{s:"Reference",d:"Identify the NCPA/agreement date, lot, tract and property address, buyer and builder."},
{s:"Date of completion",d:"Enter the completion date supported by the certificate of occupancy or final inspection; attach a copy."},
{s:"Close of escrow deadline",d:"State the COE deadline per the contract (e.g. X days after this notice) and the walk-through date."},
{s:"Delivery",d:"Builder signs; deliver to buyer, buyer's agent and escrow; keep proof of delivery. Buyer schedules the final walk-through and inspection."},
{s:"Loan timing",d:"This notice starts the funding clock: the MLO must confirm the rate lock covers the COE date (extend or re-lock), order the final 1004D/CO review and update the CD. Long build times are where locks expire."}],
"NCOU":[
{s:"Reference",d:"Enter NCPA date, lot/plan and parties. Use for options selected under the C.A.R. NCPA (the NCA-OU is the parallel version used with other new construction agreements)."},
{s:"Itemized options",d:"Itemize each option/upgrade with price and any deposit required; total the additions to the base price."},
{s:"Deposit treatment",d:"State whether upgrade deposits apply to price at close or are refundable/nonrefundable on cancellation."},
{s:"Deadlines",d:"Set selection and change-order deadlines; document every change in writing - late changes cause delays."},
{s:"Signatures and distribution",d:"Both sign; deliver to escrow and the lender. Updated price affects appraisal and LTV - forward to the MLO immediately."}],
"NCPA":[
{s:"Parties, lot and price",d:"Enter buyer, builder/seller, lot/tract/APN and address, plan/elevation, price and deposit schedule. Use only when the builder agrees to the C.A.R. form instead of its own contract."},
{s:"Financing and contingencies",d:"Complete loan terms, loan/appraisal contingency periods and buyer's investigation period. Builder may require pre-approval with its lender; buyer may still use an outside MLO."},
{s:"Estimated completion and COE",d:"Enter the estimated completion date and the outside date; COE is typically X days after the NCNC notice of completion. The MLO needs these to choose an extended lock."},
{s:"Options, upgrades and warranty",d:"Attach NCOU options addendum and the builder warranty; describe how changes and deposits are handled."},
{s:"HOA, CFD and public report",d:"Confirm delivery of the DRE public report receipt, HOA documents and Mello-Roos/CFD notices; enter dues and special taxes (DTI items)."},
{s:"Signatures and escrow",d:"All parties sign; open escrow and deliver the deposit. Attach NCA advisory and confirm buyer-broker compensation/registration in writing."}],
"NDA":[
{s:"Parties and subject",d:"Identify the disclosing party (seller/owner), receiving party (buyer and principals) and the property or business."},
{s:"Confidential information",d:"Describe covered materials: P&Ls, tax returns, leases, rent rolls, customer lists, employee data. Exclude public information."},
{s:"Permitted use and recipients",d:"Limit use to evaluating the purchase; list permitted advisors (attorney, CPA, lender). If the buyer will finance, make sure the lender is a permitted recipient."},
{s:"Return/destruction and term",d:"Specify return or destruction if no deal and the duration of the obligation."},
{s:"Signature",d:"Buyer signs and dates before any documents are released; keep with the listing file and log recipients. Do not share tenant personal information beyond what is needed."}],
"NNR":[
{s:"Owner and property",d:"Enter the owner's name, the property address and legal description (from the deed/title report). Must be completed within 10 days after the owner learns of the work."},
{s:"Work and person ordering it",d:"Describe the work of improvement and identify the tenant or other person who contracted for it; state the owner did not authorize it and is not responsible."},
{s:"Verification and signature",d:"Owner signs and verifies (declaration under penalty of perjury or notarization as the form requires - verify on the current form)."},
{s:"Posting and recording",d:"Post a copy conspicuously on the property AND record with the county recorder within the 10-day window; both are required under Civil Code 8444. Keep proof of posting (dated photo) and the recorded copy."}],
"NOE":[
{s:"Header",d:"Enter tenant names and the unit address. SkySlope holds copies -1 to -5; use the next unused number for each separate entry notice."},
{s:"Purpose of entry",d:"Check the purpose: repairs, inspection, showing to prospective buyers/tenants/lenders/appraisers, or other permitted reason under Civil Code 1954. Entry must be for a lawful purpose."},
{s:"Date and time",d:"Enter the date and an approximate time window during normal business hours. Give at least 24 hours' written notice (6 days presumed if mailed). For sale showings, oral notice is allowed only if a prior written NSE was given within 120 days."},
{s:"Service",d:"Serve personally, leave with an occupant or at the unit (posting), or mail; keep proof. Appraisers and inspectors in tenant-occupied sales need access - schedule with NOE."}],
"NPC":[
{s:"Parties and dishonored payment",d:"Identify the tenant, premises and the dishonored payment: date, amount, check/transaction number and reason (NSF, stop payment). Attach the bank notice."},
{s:"Cash-only period",d:"State the period during which rent must be paid in cash or cashier's check/money order, not exceeding three months after the dishonor (Civil Code 1947.3)."},
{s:"Service",d:"Serve properly and keep proof of service; the notice must accompany or follow the dishonor, not precede it."},
{s:"Receipts and return to normal",d:"Provide written receipts for every cash payment; calendar the end date and accept normal payment methods afterward. Demanding cash without a dishonored payment is prohibited."}],
"NRI":[
{s:"Header",d:"Enter tenant names, property address and unit, and the scheduled termination/move-out date. Give after either party serves notice ending the tenancy."},
{s:"Right to request inspection",d:"The notice explains the tenant may request an initial inspection no earlier than two weeks before move-out so they can fix deficiencies. Provide the contact and method for requesting it."},
{s:"Delivery",d:"Deliver in writing (personal, mail, email if agreed) and keep proof. Skipping NRI can jeopardize deposit deductions."},
{s:"If requested",d:"Schedule the inspection, serve the FEHN 48-hour entry notice, conduct the walk and give the PMOI statement. Keep everything in the tenant file."}],
"NSE":[
{s:"Header",d:"Enter tenant names, property address and the listing agent's name, phone and email. Serve when the tenant-occupied property is listed for sale."},
{s:"Showing plan",d:"Describe how showings will be noticed: this written notice of intent to sell allows later specific entries to be noticed orally (phone/in person) at least 24 hours ahead for 120 days under Civil Code 1954(d)(2); after 120 days a new written notice is needed."},
{s:"Service",d:"Serve by personal delivery, posting or mail; keep proof in both the listing and PM files."},
{s:"Coordination",d:"Agree a showing schedule with the tenant; excessive or unannounced showings can be harassment. Use NOE for specific appointments and leave a written note after each entry as the statute requires."}],
"NTQ":[
{s:"Occupants and premises",d:"Name every adult occupant (and 'all other occupants') and the full premises address with unit. Use after foreclosure or sale when occupants must vacate."},
{s:"Basis and notice period",d:"State the legal basis and the correct period: e.g. 3 days for a former owner after foreclosure (CCP 1161a), 90 days for a bona fide tenant (CCP 1161b and PTFA), or the lease term if a fixed-term bona fide lease exists and the buyer will not occupy. Wrong period = start over."},
{s:"Service and proof",d:"Serve by a legally permitted method and complete a proof of service; calendar the deadline."},
{s:"Next steps",d:"Track whether occupants vacate; consult a landlord-tenant attorney before any unlawful detainer. Buyers with owner-occupied financing need possession within lender occupancy deadlines - plan the timeline with the MLO."}],
"NTT":[
{s:"Header",d:"Enter tenant names, property address and unit, and the rental agreement date."},
{s:"Notice period",d:"Check 30 days (all tenants in possession less than 1 year) or 60 days (1 year or more). Add days if mailed. Local ordinances may require longer."},
{s:"Just cause",d:"If covered by AB 1482 (Civil Code 1946.2) or local just-cause rules, state the specific at-fault or no-fault reason. For owner move-in attach NTT-FM; for remodel/demolition attach NTT-RD; for withdrawal from the rental market check local Ellis Act procedures."},
{s:"Relocation assistance",d:"For no-fault terminations, state the relocation assistance (one month's rent paid within 15 days of the notice, or a rent waiver for the final month) and local amounts if higher."},
{s:"Service and proof",d:"Landlord/agent signs; serve per CCP 1162 and complete the proof of service. A wrong period or missing just cause voids the notice - attorney review recommended."}],
"NTT-FM":[
{s:"Coverage check",d:"Confirm the unit is covered by AB 1482 (or a stricter local ordinance) and, for leases signed after July 1, 2020 (and per the 2024 SB 567 amendments), that the lease allows owner/family move-in termination. Check for a comparable vacant unit on the property - if one exists, move-in termination is not allowed."},
{s:"Intended occupant",d:"Identify the owner or qualifying family member (spouse, domestic partner, child, grandchild, parent, grandparent), the relationship, and state the intent to occupy as a primary residence for at least 12 continuous months, moving in within 90 days after the tenant vacates. Tenant may request proof of the relationship."},
{s:"Relocation assistance",d:"State the method: one month's rent paid within 15 days of service, or waiver of the final month's rent, and higher local amounts where applicable."},
{s:"Tenant rights",d:"Include the statutory statement of the tenant's right to re-rent at the prior rent if the owner fails to occupy in time, and any local ordinance protections (LA, SF and others add requirements)."},
{s:"Service and calendar",d:"Serve with the NTT (60 or 90 days) and keep proof of service. Calendar move-in within 90 days and the 12-month occupancy. Buyers using owner-occupied financing must occupy within the lender's deadline (often 60 days) - coordinate the tenant's departure with the MLO."}],
"NTT-RD":[
{s:"Scope of work",d:"Describe the remodel or demolition: replacement/substantial modification of structural, electrical, plumbing or mechanical systems requiring a permit, or hazmat abatement, that cannot be done safely with tenants in place and requires vacancy of at least 30 consecutive days. Cosmetic work does not qualify."},
{s:"Permits and contract",d:"Attach copies of the permits, or if no permit is required, the signed contractor contract, plus the expected duration of the work, as SB 567 (2024) requires in the notice."},
{s:"Relocation assistance",d:"State one month's rent paid within 15 days or a waiver of the final month's rent; local ordinances often require more."},
{s:"Right to re-occupy",d:"Include the tenant's right to return at the prior rent if the work is not started or completed as described, with the statutory re-rent offer procedure (30 days to accept)."},
{s:"Service",d:"Serve with the 60- or 90-day NTT and keep proof of service. Attorney review strongly recommended - defective remodel notices draw wrongful-eviction claims."}],
"PCQ":[
{s:"Header",d:"Enter all tenant names and the complete premises address with unit. Use the next unused copy (-1 to -5) for each new notice."},
{s:"Violation and lease provision",d:"Describe the specific breach (unauthorized pet, extra occupant, nuisance) and cite or quote the lease paragraph violated. Attach photos or complaints as evidence in the file."},
{s:"Cure demand",d:"State exactly what the tenant must do to cure within 3 days (court days excluded since 2019) or quit. If the breach is incurable, use the 3-day quit notice instead - attorney call."},
{s:"Just cause note",d:"For AB 1482-covered units, a curable breach requires this notice and an opportunity to cure before a termination notice can be served."},
{s:"Service and proof",d:"Serve per CCP 1162 and complete the proof of service; keep with the evidence. Consult a landlord-tenant attorney before filing."}],
"PMA":[
{s:"Parties and properties",d:"Enter owner names (as on title or the owning entity), the managing broker (LPT Realty, if the office handles PM - confirm with LPT broker/TC), and each property and unit covered. Attach a schedule for multiple properties."},
{s:"Term and termination",d:"Set the start date, initial term, automatic renewal and each party's termination rights and notice (e.g. 30 days) plus any termination fee."},
{s:"Authority",d:"Define authority to advertise, screen and sign leases, set rent, serve notices, hire vendors, and the repair spending limit without owner approval, plus emergency authority and eviction authority."},
{s:"Compensation",d:"Enter management fee (percentage of collected rent or flat), leasing fee, renewal fee, maintenance coordination markup, vacancy fee and any fee for selling the property. Disclose all compensation from vendors."},
{s:"Trust funds and reporting",d:"Specify the trust account, owner reserve amount, security deposit holding (owner or broker), statement frequency and year-end 1099 reporting. DRE trust-fund rules (BPC 10145) apply - keep owner and tenant funds separate."},
{s:"Owner disclosures and insurance",d:"Owner confirms rent control/AB 1482 status, known defects, insurance naming the broker as additional insured, and compliance duties (smoke/CO detectors, habitability)."},
{s:"Signatures",d:"Owner and broker sign and date; set up trust accounting, RPOI/RPOD intake and the lease file."}],
"PMAD":[
{s:"Reference",d:"Enter the original PMA date, owner name and managed property address."},
{s:"Changes",d:"Describe each change precisely: revised fees, new services, properties added or removed (with addresses), new spending limits or term changes. Replace, don't annotate, the affected PMA paragraph."},
{s:"Effective date",d:"State when the changes take effect; prorate fees if mid-period."},
{s:"Signatures",d:"Owner and managing broker sign and date before changes apply; attach to the PMA in the PM file. Oral changes create fee disputes."}],
"PMOI":[
{s:"Header",d:"Enter property, unit, tenant names and the date of the pre-move-out inspection; reference the NRI and FEHN notices."},
{s:"Deficiencies by room",d:"List each item found that could be a deduction, room by room, with specifics (carpet stain in bedroom 2, broken blind)."},
{s:"Repairs the tenant may make",d:"Describe the cleaning or repair the tenant can do to avoid the deduction, consistent with the lease (some repairs may require a licensed professional)."},
{s:"Statutory text",d:"Include Civil Code 1950.5(b)(1)-(4) as required on the form; do not remove it."},
{s:"Delivery",d:"Give the statement to the tenant at the inspection or promptly after; keep a copy for the final accounting. Items not listed can still be deducted if they arise later or were hidden."}],
"PPN":[
{s:"Header",d:"Enter tenant names, premises address and unit, and the lease date."},
{s:"Amounts due",d:"Itemize first month's rent, security deposit (within the one-month cap), prorated rent and any other move-in charges; total them."},
{s:"Deadline and consequence",d:"Set the payment deadline and state that possession will not be delivered (no keys) until funds clear; note what happens if not paid (lease may be cancelled)."},
{s:"Service and file",d:"Serve in writing and keep proof; file with the lease and payment receipts. Accept cleared funds only before handing over keys."}],
"PRQ":[
{s:"Header",d:"Enter all adult tenants on the lease and the premises address with unit. Use the next unused copy (-1 to -5); do not use PRQ-CRP or PRQ-TP except for COVID-era periods."},
{s:"Amount due",d:"State ONLY rent (no late fees, utilities or other charges) owed within the past 12 months, itemized by rental period. An overstated amount voids the notice; an estimate must be labeled as such for commercial only."},
{s:"Payment instructions",d:"Enter the name, address and phone of the person to pay, the days and hours payment is accepted (or a method like mail/electronic transfer with its details) as CCP 1161(2) requires. The 2025 Eshagian v. Cepeda decision invalidated a notice that was unclear about when/how to pay - be exact."},
{s:"Notice period",d:"Three days excluding Saturdays, Sundays and judicial holidays. For CARES Act covered properties (federally backed loan or subsidy), a 30-day notice is required - attach the CFPB disclosure."},
{s:"Service and proof",d:"Serve per CCP 1162 (personal; substituted plus mail; post-and-mail) and complete the proof of service. Calendar the deadline; consult an attorney before filing the unlawful detainer."}],
"RCJC":[
{s:"Coverage determination",d:"Determine whether the unit is covered by AB 1482: generally residential units more than 15 years old, not single-family/condo owned by a natural person (with proper notice), not owner-occupied duplex, etc. Check whether local rent control or just-cause rules are stricter and supersede."},
{s:"Check the applicable box",d:"Covered: include the statutory notice of rent cap (5% + CPI, max 10%) and just-cause protections under Civil Code 1946.2 and 1947.12. Exempt: include the exemption notice in the required statutory language - without it a single-family home or condo is treated as covered."},
{s:"Exemption details",d:"For exempt SFR/condo, confirm the owner is not a REIT, corporation or LLC with a corporate member, and that the exemption language is in the lease or this addendum."},
{s:"Signatures and delivery",d:"Attach to the lease and have both parties sign at execution; for existing tenancies deliver as a written notice/addendum. Keep with the lease. Investors: rent caps limit income projections used for DSCR loans."}],
"RLAS":[
{s:"Parties and dates",d:"Enter buyer as landlord and seller as tenant, the property address, and a lease start date equal to COE. Use for seller rent-backs of 30 days or more (shorter stays use the SIP addendum)."},
{s:"Term, rent and deposit",d:"Set the term and firm move-out date, monthly rent or per-diem, and a security deposit held by the buyer (through escrow or directly). Long rent-backs can create tenant protections - keep it short."},
{s:"Utilities, maintenance and insurance",d:"Assign utilities, maintenance and repairs; require the seller to carry renter's insurance and the buyer to carry homeowner's coverage from COE."},
{s:"Disclosures",d:"Attach the lead-based paint disclosure for pre-1978 homes (LPD-RLAS) and any other required lease disclosures (TFHD, BBD, RCJC if applicable)."},
{s:"Signatures and lender",d:"All buyers and sellers sign before COE; give copies to escrow and the lender. Owner-occupied loans generally require occupancy within 60 days of close - a rent-back over 60 days conflicts with occupancy rules; clear it with the MLO first."}],
"RPOD":[
{s:"Header",d:"Enter the owner's name, mailing address and the rental property address with unit numbers. Complete before marketing the rental."},
{s:"Condition and hazards",d:"Owner answers questions on known defects, water intrusion, mold, pests, lead paint (pre-1978), asbestos, code violations and government notices; explains every Yes and attaches reports."},
{s:"Rent control and tenancy status",d:"Owner states AB 1482 coverage or exemption, local rent control/just-cause status, current and prior tenancies, pending notices and any buyout or relocation history."},
{s:"Owner signature and agent review",d:"Owner signs and dates. The agent reviews answers to identify facts that must be disclosed to prospective tenants - do not edit the owner's answers."},
{s:"File and update",d:"Store in the PM/lease file; ask the owner to update before each new tenancy or when conditions change."}],
"RPOI":[
{s:"Owner and property",d:"Enter owner names, contact and mailing address, property address, APN and number of units; note ownership entity and who signs."},
{s:"Unit and tenant detail",d:"For each unit: current tenant, rent, deposit held, lease dates, utilities paid by whom, parking, pets, and any delinquencies or notices."},
{s:"Regulatory status",d:"Note AB 1482/local rent control and just-cause status (verify independently rather than relying on the owner), HOA rules on rentals, STR permits and known defects."},
{s:"Operations",d:"Record insurance, keys/access, preferred vendors, owner reserve, screening preferences (within fair housing law) and reporting needs."},
{s:"Signature and use",d:"Owner signs and dates; keep with the LL/PMA. Use answers to drive RPOD, RCJC and lease disclosures."}],
"SALSQ":[
{s:"Header",d:"Seller enters property address, APN(s), acreage and contact information. Delivered with other seller disclosures after acceptance; seller, not the agent, answers."},
{s:"Water rights, wells and irrigation",d:"Seller discloses wells (depth, yield, logs, permits), surface water rights, water district memberships/allocations, SGMA basin status and irrigation systems; attach well logs and district statements."},
{s:"Crops, leases and chemicals",d:"Seller discloses crops and yields, farm/grazing leases, pesticide and fertilizer use and records, livestock, and any organic certifications."},
{s:"Contracts and easements",d:"Seller discloses Williamson Act/LCA contracts, conservation easements, USDA/NRCS programs, ag preserve status and government restrictions; attach the contract."},
{s:"Signatures",d:"Seller signs and dates; deliver within the disclosure period and get the buyer's signed receipt. Lender note: ag and USDA products have acreage and income-use limits - the MLO should review early."}],
"SDDA":[
{s:"Header",d:"Enter landlord, every tenant, property address and the lease date this addendum attaches to."},
{s:"Deposit amount and cap",d:"State the deposit amount. Since July 1, 2024 (AB 12) most landlords may collect no more than one month's rent total (including pet/key deposits); a natural-person owner with no more than two properties and four units total may collect two months. Verify the exemption before exceeding one month."},
{s:"Permitted deductions",d:"Describe lawful uses: unpaid rent, cleaning to return the unit to move-in condition, repair of damage beyond normal wear and tear, and restoring items per the lease. Explain the pre-move-out inspection right (NRI)."},
{s:"Return and documentation",d:"State the deposit will be returned with an itemized statement within 21 days of vacating, with receipts for deductions over $125 and photos required by AB 2801 (before/after repairs; move-in photos for tenancies starting July 1, 2025 or later)."},
{s:"Signatures",d:"Landlord and tenants sign and date; attach to the lease and keep deposit records in the PM file."}],
"STRA":[
{s:"Property and guest",d:"Enter property address, guest names, arrival/departure dates and times, maximum occupants and vehicles. Confirm the city/county STR permit and HOA CC&Rs allow short-term rentals before booking."},
{s:"Rent, fees and TOT",d:"Enter total rent, cleaning and other fees, transient occupancy tax (TOT) rate and amount, and payment due dates. Collect and remit TOT where required."},
{s:"Deposit and cancellation",d:"Set the security deposit, inspection and refund timing, damage charges and the cancellation/refund policy."},
{s:"House rules",d:"Attach rules on noise, parking, pets, trash, smoking, pool and HOA rules, plus an inventory if furnished items are significant."},
{s:"Signatures",d:"Both sign before check-in. Stays of 30+ days can create tenancy rights under landlord-tenant law - use a lease instead for longer stays."}],
"STRA-SA":[
{s:"Reference",d:"Enter the STRA date, property and guest names."},
{s:"Seasonal periods and rates",d:"List each seasonal period with dates and the rate for that period, and any minimum-stay or blackout dates."},
{s:"Services",d:"Address utilities, pool/yard/snow services, linen and cleaning schedules during the season."},
{s:"Deposit and cancellation changes",d:"Note any changes to deposit or cancellation terms for the seasonal arrangement."},
{s:"Signatures",d:"Both sign; attach to the STRA. Watch the 30-day threshold - continuous occupancy longer than 30 days can convert the arrangement into a tenancy."}],
"SUM-MII":[
{s:"Header",d:"Enter property, unit, tenant names and move-in date; reference the detailed MII."},
{s:"Itemized existing conditions",d:"Summarize each room/item with existing damage or wear noted on the MII so both parties agree on the baseline."},
{s:"Photos",d:"Reference attached dated photos/video. For tenancies beginning on or after July 1, 2025, AB 2801 requires move-in photos to support later deposit deductions."},
{s:"Signatures and file",d:"Both sign and date; give the tenant a copy and file with the lease for move-out comparison."}],
"SUM-MOI":[
{s:"Header",d:"Enter unit, tenant names and move-out date; reference the SUM-MII and MOI."},
{s:"Damage beyond wear and tear",d:"Compare to move-in and list only damage beyond normal wear and tear; separate cleaning from repair."},
{s:"Photos",d:"Attach dated photos taken after move-out and after repairs/cleaning as AB 2801 requires."},
{s:"Costs",d:"Record repair/cleaning estimates or invoices for the itemized statement (receipts required for deductions over $125)."},
{s:"Signature and deadline",d:"Sign; send the itemized statement, photos and any refund within 21 days of move-out under Civil Code 1950.5."}],
"SUM-PMOI":[
{s:"Header",d:"Enter unit, tenant names and inspection date; reference the NRI and the PMOI statement."},
{s:"Items the tenant may correct",d:"List each cleaning or repair item the tenant can fix before vacating to avoid a deduction."},
{s:"Photos and statement",d:"Reference the PMOI statement and photos taken at the inspection."},
{s:"Delivery and use",d:"Give the tenant a copy at the inspection or promptly after; keep for comparison at the final move-out inspection (Civil Code 1950.5(f))."}],
"TEC":[
{s:"Header",d:"Fill in property, unit, tenant names and lease date. One estoppel per tenant/unit (TEC Buyer 1-4 copies in SkySlope); request early in the contingency period."},
{s:"Lease terms",d:"Pre-fill from landlord records: rent, due date, deposit, term start/end, options, prepaid rent, parking/storage, who pays utilities. Tenant confirms or corrects."},
{s:"Defaults and side agreements",d:"Tenant states any landlord defaults, unperformed repairs, disputes, rent concessions, or oral/side agreements not in the lease."},
{s:"Signature and delivery",d:"Tenant signs and dates; deliver to buyer within the contract time. Tenants are not obligated to sign unless the lease requires it - allow time."},
{s:"Review",d:"Buyer compares against the rent roll before removing contingencies. Lenders on 2-4 unit and commercial property often require estoppels to verify rental income."}],
"TFHD":[
{s:"Header",d:"Enter property address, landlord and tenant names. Required for every residential lease since July 1, 2018 (Gov. Code 8589.45)."},
{s:"Flood hazard knowledge",d:"Check whether the landlord has actual knowledge the property is in a special flood hazard area or area of potential flooding (FEMA map, lender flood notice, prior flooding)."},
{s:"Insurance information",d:"The pre-printed text tells the tenant the landlord's insurance does not cover tenant property and how to get flood insurance and FEMA information; do not edit."},
{s:"Signatures",d:"Attach to the lease; both sign; keep with the lease. Required even when the property is not in a flood zone."}],
"TRPR":[
{s:"Header",d:"Enter landlord name, every tenant and the property address/unit. AB 2747 (Civil Code 1954.07) requires covered landlords to offer this at lease signing (leases on/after April 1, 2025) and at least annually thereafter."},
{s:"Coverage",d:"Owners of a single building with 15 or fewer units are generally exempt unless they own more than one rental building or are a REIT/corporation/LLC with a corporate member - verify."},
{s:"Fee",d:"State the monthly fee: the lesser of $10 or the landlord's actual cost; no fee if there is no cost. Non-payment of the fee cannot be grounds for termination or a deposit deduction."},
{s:"Election",d:"Tenant checks accept or decline; the form names the reporting agency(ies) and explains opt-out rights (opt out any time; re-enroll after six months)."},
{s:"Signature and follow-up",d:"Tenant signs and dates; landlord keeps the election with the lease, enrolls accepting tenants with the reporting service and re-offers annually. Positive rent reporting can help future mortgage qualification."}],
"VRA":[
{s:"Guest and dates",d:"Enter guest name and contact, property address, check-in/check-out dates and times and maximum occupants."},
{s:"Rent, fees and taxes",d:"Enter rent, cleaning fee, security deposit, transient occupancy tax and payment schedule; many cities require an STR permit number on advertising and collection of TOT."},
{s:"House rules and cancellation",d:"Complete rules on pets, smoking, parking, noise/quiet hours and occupancy; set cancellation and refund terms."},
{s:"Attachments",d:"Attach HOA rules and local STR permit conditions the guest must follow."},
{s:"Signatures",d:"Guest signs and returns with payment; owner/broker countersigns and sends the executed copy. Stays of 30+ days create tenancy rights - use a lease instead."}],
"WSM":[
{s:"Header",d:"Enter landlord, tenant, property address and the lease date. Use when the unit is submetered for water (Water Code 537 et seq.)."},
{s:"Submeter description",d:"Describe the submeter, the unit it serves, its location and how and when readings are taken each billing period."},
{s:"Billing method",d:"State the billing cycle, how the tenant's charge is computed (actual usage at the utility's rate, no estimates), any administrative fee within the statutory limit, and payment due dates."},
{s:"Required disclosures",d:"Include the statutory disclosures: dispute procedure, meter location and testing rights, and the statement that water charges are separate from rent (verify on the current form)."},
{s:"Signatures and records",d:"Landlord and tenants sign and date; attach to the lease and keep billing records in the property file."}]
});
